@CrossOrigin
@RestController
@RequestMapping("/PlantQuery")
public class PlantQueryRestController extends BaseSpringRestController {
	
	public PlantQueryRestController( PlantService service ) {
        this.service = service;
    }
    
    /**
     * Handles loading a Plant using a UUID
     * @param		UUID plantId
     * @return		Plant
     */    
    @GetMapping("/load")
    public Plant load( @RequestParam(required=true) UUID plantId ) {
    	Plant entity = null;

    	try {  
    		entity = service.getPlant( new PlantFetchOneSummary( plantId ) );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING, "failed to load Plant using Id " + plantId );
            return null;
        }

        return entity;
    }

    /**
     * Handles loading all Plant business objects
     * @return		Set<Plant>
     */
    @GetMapping("/")
    public List<Plant> loadAll() {                
    	List<Plant> plantList = null;
        
    	try {
            // load the Plant
            plantList = service.getAllPlant();
            
            if ( plantList != null )
                LOGGER.log( Level.INFO,  "successfully loaded all Plants" );
        }
        catch( Throwable exc ) {
            LOGGER.log( Level.WARNING,  "failed to load all Plants ", exc );
        	return null;
        }

        return plantList;
                            
    }



//************************************************************************    
// Attributes
//************************************************************************
    protected Plant plant = null;
    protected PlantService service = null;
    private static final Logger LOGGER = Logger.getLogger(PlantQueryRestController.class.getName());
    
}
